import json, os, shutil, subprocess, sys, tempfile, time
B = sys.argv[1]; H = f"{B}/harness"
sys.path.insert(0, H); import mockprovider as mp
def fresh(): return tempfile.mkdtemp(dir=f"{B}/work")
os.makedirs(f"{B}/work", exist_ok=True)
def run(fw, w, *a, **env):
    py = {"lg": f"{B}/lg/bin/python", "oa": f"{B}/oa/bin/python", "cp": f"{B}/lg/bin/python"}[fw]
    t = time.perf_counter()
    p = subprocess.run([py, f"{H}/{fw}_bench.py", *a], capture_output=True, text=True, timeout=120,
        env={"PATH": os.environ["PATH"], "W": w, "OPENAI_API_KEY": "", **{k: str(v) for k, v in env.items()}})
    ms = (time.perf_counter() - t) * 1000
    try: o = json.loads(p.stdout.strip().splitlines()[-1])
    except Exception: o = None
    return {"rc": p.returncode, "out": o, "err": p.stderr.strip().splitlines()[-1][:220] if p.stderr.strip() else "", "ms": round(ms)}
R = {}
def rec(k, **v): R[k] = v; print(k, json.dumps(v)[:600], flush=True)
S = lambda w: mp.count(f"{w}/sends.jsonl")
# ---------- LangGraph
w = fresh(); a = run("lg", w, "start", "t1"); b = run("lg", w, "resume", "t1", "approved")
rec("lg.restart_then_approve", sends=S(w), next=b["out"]["next"], status=b["out"]["values"].get("status"), start_ms=a["ms"], resume_ms=b["ms"], db_bytes=os.path.getsize(f"{w}/lg.sqlite"))
w = fresh(); run("lg", w, "start", "t1"); pe1 = open(f"{w}/pre_interrupt_effect.count").read(); run("lg", w, "reinvoke", "t1"); run("lg", w, "resume", "t1", "approved")
rec("lg.preinterrupt_effect_reexecuted", notify_count_after_start=pe1, notify_count_after_resume=open(f"{w}/pre_interrupt_effect.count").read(), sends=S(w))
w = fresh(); run("lg", w, "start", "t1"); c = run("lg", w, "reinvoke", "t1")
rec("lg.reinvoke_without_approval", sends=S(w), next=c["out"]["next"] if c["out"] else None, rc=c["rc"])
w = fresh(); run("lg", w, "start", "t1"); c = run("lg", w, "resume", "t1", "rejected")
rec("lg.rejected", sends=S(w), status=c["out"]["values"].get("status"))
for dur in ("sync", "async", "exit"):
    w = fresh(); run("lg", w, "start", "t1"); x = run("lg", w, "resume", "t1", "approved", CRASH_AFTER_SEND=1, DUR=dur); y = run("lg", w, "reinvoke", "t1", DUR=dur)
    rec(f"lg.crash_after_send_no_idem.{dur}", crash_rc=x["rc"], sends_after_recovery=S(w), next=y["out"]["next"] if y["out"] else None, err=y["err"])
w = fresh(); run("lg", w, "start", "t1"); run("lg", w, "resume", "t1", "approved", CRASH_AFTER_SEND=1, USE_IDEM=1); y = run("lg", w, "reinvoke", "t1", USE_IDEM=1)
rec("lg.crash_after_send_provider_idem", sends_after_recovery=S(w), next=y["out"]["next"] if y["out"] else None, external_ref=y["out"]["values"].get("external_ref") if y["out"] else None)
w = fresh(); run("lg", w, "start", "t1"); run("lg", w, "resume", "t1", "approved"); d = run("lg", w, "resume", "t1", "approved")
rec("lg.duplicate_approval_event", sends=S(w), next=d["out"]["next"], reply_field=d["out"]["values"].get("reply"), status=d["out"]["values"].get("status"))
w = fresh(); a = run("lg", w, "start", "t1"); iid = a["out"]["interrupts"][0]["id"]; run("lg", w, "resume", "t1", "approved"); d = run("lg", w, "resume_stale", "t1", iid)
rec("lg.duplicate_approval_keyed_to_stale_interrupt_id", sends=S(w), rc=d["rc"], err=d["err"], next=d["out"]["next"] if d["out"] else None, reply_field=d["out"]["values"].get("reply") if d["out"] else None)
w = fresh(); run("lg", w, "start", "t1"); run("lg", w, "tamper", "t1", "PWNED body"); d = run("lg", w, "resume", "t1", "approved")
rec("lg.payload_changed_after_approval_shown", sends=S(w), delivered_to=[r["to"] for r in mp.rows(f"{w}/sends.jsonl")], rc=d["rc"])
w = fresh(); run("lg", w, "start", "tenantA"); d = run("lg", w, "resume", "tenantA", "approved")
rec("lg.other_tenant_with_thread_id_can_resume", sends=S(w), note="harness passes no identity because the API has none; scoping is the caller's job")
w = fresh(); run("lg", w, "start", "t1"); d = run("lg", w, "resume", "t1", "approved", VARIANT="v2")
rec("lg.deploy_renames_paused_node", rc=d["rc"], err=d["err"], sends=S(w), next=d["out"]["next"] if d["out"] else None, status=d["out"]["values"].get("status") if d["out"] else None)
w = fresh(); run("lg", w, "start", "t1"); d = run("lg", w, "resume", "t1", "approved", FAIL_FIRST=2, RETRIES=3)
rec("lg.transient_failure_with_retry_policy", sends=S(w), attempts=open(f"{w}/sends.jsonl.attempts").read(), next=d["out"]["next"])
w = fresh(); run("lg", w, "start", "t1"); d = run("lg", w, "resume", "t1", "approved", FAIL_FIRST=9, RETRIES=2); e = run("lg", w, "reinvoke", "t1", FAIL_FIRST=0)
rec("lg.retries_exhausted_then_recover", rc=d["rc"], err=d["err"], sends_after=S(w), recovered_next=e["out"]["next"] if e["out"] else None)
w = fresh(); run("lg", w, "start", "t1"); raw = open(f"{w}/lg.sqlite", "rb").read()
rec("lg.checkpoint_plaintext", contains_recipient=b"vendor@example.test" in raw, contains_body=b"gutter cleaning at 12 Elm" in raw, db_bytes=len(raw))
# ---------- OpenAI Agents SDK
w = fresh(); a = run("oa", w, "start"); b = run("oa", w, "approve")
rec("oa.restart_then_approve", sends=S(w), interruptions=a["out"]["interruptions"] if a["out"] else a["err"], final=b["out"]["final_output"] if b["out"] else b["err"], start_ms=a["ms"], resume_ms=b["ms"], state_bytes=os.path.getsize(f"{w}/state.json") if os.path.exists(f"{w}/state.json") else None)
w = fresh(); run("oa", w, "start"); c = run("oa", w, "reject")
rec("oa.rejected", sends=S(w), final=c["out"]["final_output"] if c["out"] else c["err"])
w = fresh(); run("oa", w, "start"); x = run("oa", w, "approve", CRASH_AFTER_SEND=1); y = run("oa", w, "approve")
rec("oa.crash_after_send_reapprove_from_saved_state", crash_rc=x["rc"], sends_after_recovery=S(w), final=y["out"]["final_output"] if y["out"] else y["err"])
w = fresh(); run("oa", w, "start"); run("oa", w, "approve"); d = run("oa", w, "approve")
rec("oa.duplicate_approval_event", sends=S(w), rc=d["rc"], final=d["out"]["final_output"] if d["out"] else d["err"])
w = fresh(); run("oa", w, "start"); run("oa", w, "tamper", "attacker@example.test"); d = run("oa", w, "approve")
rec("oa.payload_changed_in_saved_state", sends=S(w), delivered_to=[r["to"] for r in mp.rows(f"{w}/sends.jsonl")], rc=d["rc"], err=d["err"])
w = fresh(); run("oa", w, "start"); d = run("oa", w, "approve", FAIL_ALWAYS=1)
rec("oa.tool_failed_but_model_says_done", sends=S(w), final=d["out"]["final_output"] if d["out"] else d["err"], rc=d["rc"])
w = fresh(); run("oa", w, "start"); d = run("oa", w, "approve", AGENTNAME="gutter_v2")
rec("oa.deploy_renames_agent", rc=d["rc"], err=d["err"], sends=S(w))
w = fresh(); run("oa", w, "start"); d = run("oa", w, "approve", TOOLNAME="send_vendor_email_v2")
rec("oa.deploy_renames_tool", rc=d["rc"], err=d["err"], sends=S(w), final=d["out"]["final_output"] if d["out"] else None)
w = fresh(); run("oa", w, "start"); raw = open(f"{w}/state.json","rb").read()
rec("oa.state_plaintext", contains_recipient=b"vendor@example.test" in raw, state_bytes=len(raw))
# ---------- Control-plane baseline
w = fresh(); a = run("cp", w, "start", "r1", "hhA"); b = run("cp", w, "approve", "r1", "hhA", "e1")
rec("cp.restart_then_approve", sends=S(w), state=b["out"]["state"], start_ms=a["ms"], resume_ms=b["ms"])
w = fresh(); run("cp", w, "start", "r1", "hhA"); x = run("cp", w, "approve", "r1", "hhA", "e1", CRASH_AFTER_SEND=1); y = run("cp", w, "recover")
rec("cp.crash_after_send_no_provider_idem", crash_rc=x["rc"], sends_after_recovery=S(w), state=y["out"])
w = fresh(); run("cp", w, "start", "r1", "hhA"); x = run("cp", w, "approve", "r1", "hhA", "e1", CRASH_AFTER_SEND=1, PROVIDER_IDEM=1); y = run("cp", w, "recover", PROVIDER_IDEM=1)
rec("cp.crash_after_send_provider_idem", sends_after_recovery=S(w), state=y["out"])
w = fresh(); run("cp", w, "start", "r1", "hhA"); run("cp", w, "approve", "r1", "hhA", "e1"); d = run("cp", w, "approve", "r1", "hhA", "e1"); d2 = run("cp", w, "approve", "r1", "hhA", "e2")
rec("cp.duplicate_approval_event", sends=S(w), same_event=d["out"], new_event=d2["out"])
w = fresh(); run("cp", w, "start", "r1", "hhA"); run("cp", w, "tamper", "r1", "attacker@example.test"); d = run("cp", w, "approve", "r1", "hhA", "e1")
rec("cp.payload_changed_after_approval_shown", sends=S(w), out=d["out"])
w = fresh(); run("cp", w, "start", "r1", "hhA"); d = run("cp", w, "approve", "r1", "hhB", "e1")
rec("cp.other_tenant", sends=S(w), out=d["out"])
w = fresh(); run("cp", w, "start", "r1", "hhA"); d = run("cp", w, "reply", "r1", "hhA", "e9", "confirmed")
rec("cp.reply_before_send_rejected", out=d["out"], sends=S(w))
json.dump(R, open(f"{B}/results.json", "w"), indent=1)
